using System.IdentityModel.Tokens.Jwt;using MediDesk.Api.Authorization;using MediDesk.Business.Interfaces;using MediDesk.Common.Contracts.Catalog;using MediDesk.Common.Contracts.Finance;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;namespace MediDesk.Api.Controllers{[ApiController][Route("api/accounts")][Authorize(Policy=PermissionPolicies.AccountsView)]public sealed class AccountsController(IAccountService s):ControllerBase{[HttpGet]public async Task<ActionResult<PagedResponse<AccountEntryDto>>>Get([FromQuery]AccountQuery q,CancellationToken ct)=>Ok(await s.GetPageAsync(q,ct));[HttpPost][Authorize(Policy=PermissionPolicies.AccountsAdd)]public async Task<ActionResult<AccountEntryDto>>Create(CreateAccountEntryRequest r,CancellationToken ct)=>Ok(await s.CreateAsync(r,long.Parse(User.FindFirst(JwtRegisteredClaimNames.Sub)!.Value),ct));}}

